"""Writes docs/adr/NNNN-*.md from the decisions in vayu-swachh-spec.md section 3, with where each is implemented."""
from pathlib import Path

OUT = Path(__file__).resolve().parents[1] / "docs" / "adr"
OUT.mkdir(parents=True, exist_ok=True)

ADRS = [
    ("01", "multi-agent-architecture", "Multi-agent architecture on the IBM Bob framework",
     "Six specialised agents run as workers and communicate only through an event bus, never by direct calls. Each has an independent failure domain; every agent must be idempotent and tolerate duplicate or out-of-order events.",
     "Implemented in `services/agents/` on a small in-repo base class (`common/agent.py`): subscription by event type, idempotency on `event_id`, ack-after-success redelivery, health report. **Deviation:** the IBM Bob SDK (`ibm-bob`) is not a public package, so `BaseAgent` provides the same pub/sub, state-snapshot and health contract; swap it behind `BaseAgent` when the SDK is available. The six agents currently share one process and an in-memory `World`; Redis-backed `RedisStreamsBus`/`RedisState` exist for the split into separate deployments."),
    ("02", "redis-event-bus", "Redis as the event bus and shared state store",
     "Redis Streams carry domain events; Redis also holds shared state snapshots and distributed locks. Durable event history is kept in PostgreSQL through an outbox table so Redis can be rebuilt.",
     "`agents/common/bus.py` (`RedisStreamsBus`: one stream per event type, a consumer group per agent, XACK after success), `outbox.py` (SQLite in dev, `outbox` table in the Postgres migration), `state.py`, `idempotency.py`. Per-parcel rate limits use Redis counters (`integrations/ratelimit.py`)."),
    ("03", "postgres-postgis-timescale", "PostgreSQL with PostGIS and TimescaleDB",
     "PostGIS stores spatial geometry (parcels, villages, grid cells, streets); TimescaleDB stores sensor and AQI time series. Migrations enable both extensions and create hypertables.",
     "`db/migrations/versions/0001_schema.py` (Alembic). Verified statically in CI; the up/down test against a real database runs when `VAYU_TEST_DATABASE_URL` is set. The running API still uses in-memory repositories: wiring the SQL repositories is the next step."),
    ("04", "fastapi-python", "FastAPI for the API layer, Python throughout",
     "All backend services are Python. FastAPI serves REST and WebSocket; Pydantic types the contract; OpenAPI is generated.",
     "`services/api/`. Written for Python 3.12 but avoids 3.12-only syntax and is tested on 3.11, the interpreter available during development."),
    ("05", "contract-first-api", "Typed contract-first API",
     "The OpenAPI document is the contract and the TypeScript client is generated from it, so front end and backend can be built against mocks and protected by contract tests.",
     "`scripts/export_contracts.py` writes `packages/contracts/openapi.json` (3.1) and the event JSON Schemas; `--check` fails CI on drift. `npm run gen:api` generates `apps/web/src/api-client/schema.d.ts`, which types the HTTP client path set. Most response bodies are still plain dicts in the schema; promoting them to Pydantic response models is the way to make response types generated too."),
    ("06", "phone-masking", "Phone number masking by default",
     "Farmer phone numbers are masked (`98721-XXXXX`) in every API response and UI display. The only exception is the assigned machinery operator on a confirmed booking, shown to the farmer and FPO coordinator for that booking.",
     "`api/masking.py`: every JSON response passes through `MaskedJSONResponse`, so a handler cannot leak a number by forgetting to mask; the single exception is the explicit `clear()` wrapper used in `booking_view` for confirmed bookings. Tested in `tests/contract/test_api.py`."),
    ("07", "two-person-diversion", "Two-person approval for diversion orders",
     "A directive that diverts traffic needs a second `policy_officer` approver, and every directive is written to an immutable audit log before dispatch.",
     "`api/directives.py` + `api/audit.py` (hash-chained). The same rule is a `CHECK` constraint in the `directive` table, and the audit table has an append-only trigger."),
    ("08", "economics-first-scripts", "Economics-first farmer communication",
     "Farmer scripts state prices and earnings directly and avoid punitive wording.",
     "`packages/domain/config/farmer_scripts_v1.yaml` holds the templates (rates are not in it: ADR-17) and a per-language blocked-word list; `render_script` refuses to emit a script containing one. Punjabi and Hindi copy is machine-drafted and needs native review."),
    ("09", "keypad-first", "Keypad-first farmer interaction",
     "Farmers act by pressing 1, 2 or 9; no app or text input.",
     "`POST /v1/calls/keypress` (simulator) and the signed telephony webhook share `Ops.handle_key`: 1 books and confirms a machine, 2 requests straw collection at the floor price, 9 requests an agronomist callback."),
    ("10", "bhashini-audio-cache", "Audio library first, Bhashini optional",
     "Farmer call audio comes from a library of pre-recorded Punjabi and Hindi clips keyed by script hash. Bhashini TTS is optional behind `TTS_PROVIDER=bhashini`, cached by SHA-256 of the normalised script. There is no speech recognition.",
     "`integrations/audio` (library, static DTMF prompts, provider choice) and `integrations/bhashini` (TTS adapter and cache). The clips themselves are recorded by native speakers before the pilot; until then `AudioLibrary.coverage` lists what is missing."),
    ("11", "mock-first-frontend", "Mock-first front end",
     "The front end is built against typed mock fixtures that match the contract; one environment variable switches to the live API.",
     "`apps/web/src/mocks` and `VITE_API_MODE=mock|live`. The UI-facing `VayuApi` interface is kept stable; `src/api/live.ts` adapts the spec endpoints onto it (covered by `tests/unit/live-adapter.test.ts`)."),
    ("12", "citizen-photo-privacy", "Privacy for citizen photo reports",
     "Photo uploads are stripped of EXIF except the GPS point, which is stored as a coarse grid reference; reports get a reference ID and no personal identifiers.",
     "`api/images.py` re-encodes the pixels into a new image (no metadata carried over) and writes only a GPS IFD rounded to a ~1 km grid. Tested by reading the saved file's EXIF."),
    ("13", "exotel-primary-twilio-standby", "Exotel primary telephony, Twilio standby",
     "Exotel places outbound IVR calls; Twilio is a hot standby behind the same adapter. Calls are enabled only after gate G1 (telecom compliance).",
     "`integrations/telephony`: Exotel and Twilio providers, signed webhooks, failover after 3 failed health checks, calling hours from `config/telephony.yaml`. `Settings.telephony_primary` defaults to `exotel`. `/calls/trigger` returns 503 while `TELEPHONY_ENABLED` is off."),
    ("14", "recommendations-not-transmissions", "Traffic diversions are recommendations, not transmissions",
     "The platform never sends anything to traffic authorities. An approved diversion becomes a signed PDF advisory that a policy officer downloads and sends through official channels.",
     "`api/directives.py` (`export`), `api/advisory_pdf.py` (PDF + Ed25519 signature), `GET /v1/directives/{id}/export`. The old traffic sender is deleted; `tests/contract/test_directive_export.py` asserts no network client is imported by the export path. The signing method is a gate G2 decision."),
    ("15", "supervisor-portal", "MCD dispatch through our supervisor portal",
     "The platform owns the work-order workflow. Supervisors accept and complete orders in `/ops` with a photo and GPS. There is no MCD API dependency.",
     "`api/workorders.py`, `api/routers/workorders.py`, `apps/web/src/routes/ops`. `integrations/mcd` is a no-op notifier seam only. Every transition writes a `work_order_event`."),
    ("16", "open-licence-forecast-kriging", "Open-licence forecast inputs with kriging downscaling",
     "CAMS grids and ERA5 meteorology feed the forecast, CPCB observations correct it, and kriging with external drift on OpenStreetMap covariates downscales to 1 km. No GNN, no WRF-Chem in the pilot.",
     "`ingestion/cams.py`, `ingestion/era5.py`, `ingestion/osm.py`, `agents/forecast_agent` (`kriging.py`, `correction.py`, `downscale.py`), `config/forecast.yaml`. The GNN path stays in the code behind `FORECAST_GNN_ENABLED` (default OFF). The OSM covariate file is a placeholder until the extract job exists."),
    ("17", "rates-weights-tiers-are-config", "Partner rates, risk weights, and GRAP tiers are configuration",
     "Floor prices, subsidy rates, risk weights and GRAP tiers live in versioned config. Farmer-facing rates are rendered only from an active contract.",
     "`config/partner_rates.yaml`, `config/risk_weights.yaml`, `config/grap_tiers.yaml`; `domain/partners.py` returns no rate unless a contract is `active`; `render_script` omits a priced line without one; tables `partner_contract` and `partner_rate` in migration 0002."),
    ("18", "disclaimers-from-config", "Required disclaimers, served from config",
     "Citizen advice is exposure guidance, not medical advice; directives are recommendations to authorities. The wording is config so legal can change it without a release.",
     "`config/disclaimers.yaml`, `domain/disclaimers.py`, `GET /v1/config/public`, `apps/web/src/routes/citizen/Disclaimer.tsx`, and the signed advisory PDF."),
    ("19", "external-features-behind-flags", "Externally facing features behind flags",
     "Anything that sends content to the public or an external party sits behind a flag that defaults to OFF. Enabling an externally facing flag needs two different admins.",
     "`config/features.yaml`, `domain/features.py`, `PUT /v1/admin/features/{name}`. Defaults are checked against the spec table by `tests/unit/test_features.py`."),
    ("20", "open-licence-source-policy", "Open-licence source policy",
     "Only sources with an open or permissive licence are ingested. Each is registered with its licence, attribution and redistribution rule, and attribution is shown wherever derived data appears.",
     "`domain/data_sources.py` (registry and seed), `data_source` table in migration 0002, `docs/data-licences.md` (generated), `design-system/DataAttribution.tsx`. Every connector calls `require()` and refuses an unregistered source. The Open-Meteo NWP forecast is registered as `nwp` because the 72 h plume needs forecast winds that ERA5 cannot give."),
    ("21", "baseline-without-sangrur-stations", "Baseline does not depend on Sangrur ground stations",
     "The fire baseline comes from FIRMS, the air-quality baseline from CPCB stations in Delhi, and effects are estimated by difference-in-differences against unaffected Delhi stations.",
     "`ingestion/baseline.py`, `scripts/load_baseline.py`, `config/baseline.yaml`; details and the open data item in ADR-23."),
    ("22", "agronomist-queue-or-callback", "Keypad 9 routes to a staffed agronomist queue",
     "Pressing 9 queues the farmer for a human agronomist in pilot hours, otherwise offers a callback slot. If neither is configured the request is recorded and no response time is promised.",
     "`api/agronomist.py`, `config/agronomist.yaml`, `Ops.handle_key`. Gate G4."),
]

for num, slug, title, decision, impl in ADRS:
    (OUT / f"00{num}-{slug}.md").write_text(
        f"# ADR-{num}: {title}\n\n**Status:** Accepted (from vayu-swachh-spec.md section 3)\n\n## Decision\n\n{decision}\n\n## Implementation\n\n{impl}\n", encoding="utf8")
print("wrote", len(ADRS), "ADRs")
